package release

import (
	"errors"
	"fmt"
	"math"
	"regexp"
	"strconv"
	"strings"
)

// gramsMilli 以千分之一克为单位定点存储克数，避免浮点误差。
type gramsMilli int64

// maxGramsMilli 是同一批次内每种物料累计实投的上限，
// 即 9223372036854775.807 克（math.MaxInt64 个千分之一克）。
const maxGramsMilli gramsMilli = math.MaxInt64

// feedingAccumulator 按物料累计一个批次内的实投量（千分之一克）。
// 追加投料、读取台账校验与批次数量核对共用这一套数量规则：
// 累计范围始终是一个批次中的一种物料，其他物料与其他批次的数量
// 不参与，物料之间也不互相抵消；任一物料的累计上限为 maxGramsMilli，
// 恰好达到上限合法，再增加 0.001 克即判超限。累计不回绕、不截断、
// 不舍入，精确到千分之一克。
type feedingAccumulator struct {
	sums map[string]gramsMilli
}

func newFeedingAccumulator() *feedingAccumulator {
	return &feedingAccumulator{sums: map[string]gramsMilli{}}
}

// add 计入一条该物料的投料；计入后会超过上限时返回 false 且不计入，
// 已有累计保持不变。
func (a *feedingAccumulator) add(materialNo string, g gramsMilli) bool {
	sum := a.sums[materialNo]
	if g > maxGramsMilli-sum {
		return false
	}
	a.sums[materialNo] = sum + g
	return true
}

// total 返回该物料的累计实投量；无投料记录时为零。
func (a *feedingAccumulator) total(materialNo string) gramsMilli {
	return a.sums[materialNo]
}

var gramsPattern = regexp.MustCompile(`^(\d+)(?:\.(\d{1,3}))?$`)

// parseGrams 将克数字符串精确解析为千分之一克。
// 规则：必须为正数，且最多三位小数（如 100、100.5、0.001 合法；0、-1、1.2345 非法）。
func parseGrams(s string) (gramsMilli, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0, errors.New("克数不能为空")
	}
	m := gramsPattern.FindStringSubmatch(s)
	if m == nil {
		return 0, fmt.Errorf("克数 %q 不合法：必须为正数且最多三位小数", s)
	}
	whole, err := strconv.ParseInt(m[1], 10, 64)
	if err != nil {
		return 0, fmt.Errorf("克数 %q 不合法", s)
	}
	var frac int64
	if m[2] != "" {
		f := m[2]
		for len(f) < 3 {
			f += "0"
		}
		frac, err = strconv.ParseInt(f, 10, 64)
		if err != nil {
			return 0, fmt.Errorf("克数 %q 不合法", s)
		}
	}
	// 先做溢出检查，避免整数回绕把超大克数变成较小的值。
	if whole > int64(maxGramsMilli)/1000 ||
		(whole == int64(maxGramsMilli)/1000 && frac > int64(maxGramsMilli)%1000) {
		return 0, fmt.Errorf("克数 %q 超出范围：单次数量不能超过 %s 克", s, maxGramsMilli)
	}
	milli := whole*1000 + frac
	if milli <= 0 {
		return 0, fmt.Errorf("克数 %q 必须为正数", s)
	}
	return gramsMilli(milli), nil
}

var signedGramsPattern = regexp.MustCompile(`^(-?)(\d+)(?:\.(\d{1,3}))?$`)

// parseSignedGrams 将允许零与负数的克数字符串精确解析为千分之一克。
// 用于读取核对中比较应投量、实投量与差额：实投可以为零，差额可以为负，
// 这些都不是非法数量。规则与 parseGrams 相同（最多三位小数、不超出可
// 表示范围），只多允许一个前导负号与零值；1.000 与 1 是同一数量。
func parseSignedGrams(s string) (gramsMilli, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0, errors.New("克数不能为空")
	}
	m := signedGramsPattern.FindStringSubmatch(s)
	if m == nil {
		return 0, fmt.Errorf("克数 %q 不合法：最多三位小数", s)
	}
	whole, err := strconv.ParseInt(m[2], 10, 64)
	if err != nil {
		return 0, fmt.Errorf("克数 %q 不合法", s)
	}
	var frac int64
	if m[3] != "" {
		f := m[3]
		for len(f) < 3 {
			f += "0"
		}
		frac, err = strconv.ParseInt(f, 10, 64)
		if err != nil {
			return 0, fmt.Errorf("克数 %q 不合法", s)
		}
	}
	// 与 parseGrams 相同的溢出检查，避免整数回绕。
	if whole > int64(maxGramsMilli)/1000 ||
		(whole == int64(maxGramsMilli)/1000 && frac > int64(maxGramsMilli)%1000) {
		return 0, fmt.Errorf("克数 %q 超出范围：不能超过 %s 克", s, maxGramsMilli)
	}
	milli := whole*1000 + frac
	if m[1] == "-" {
		milli = -milli
	}
	return gramsMilli(milli), nil
}

// String 将千分之一克格式化为克数字符串，去掉末尾多余的 0。
func (g gramsMilli) String() string {
	sign := ""
	v := int64(g)
	if v < 0 {
		sign = "-"
		v = -v
	}
	w, f := v/1000, v%1000
	if f == 0 {
		return sign + strconv.FormatInt(w, 10)
	}
	fs := strings.TrimRight(fmt.Sprintf("%03d", f), "0")
	return sign + strconv.FormatInt(w, 10) + "." + fs
}

// multiplyPortions 将每份克数与计划份数相乘，计算某物料的应投量
// （每份克数 × 计划份数）。它是数量规则 planRequirements 使用的底层
// 定点运算，创建批次、调整草稿、读取校验与批次数量核对最终都经由
// planRequirements 调用到这里：
//   - 计划份数必须为正整数——份数为零或负数的已保存批次即数据损坏，
//     也不能据此算出零或负的应投量；
//   - 相乘结果必须能用千分之一克（int64 个 milli）精确表示：克数本身
//     已是千分之一克的整数倍，整数相乘不引入更小的单位，不存在舍入；
//     结果超过 maxGramsMilli（9223372036854775.807 克）时返回错误。
//
// 这里只做一种物料一次乘法，按物料分别判断上限的职责在 planRequirements：
// 不与同批次其他物料的应投量相加；恰好等于上限合法，再大即溢出。
// 计算不回绕、不截断、不舍入。
func multiplyPortions(g gramsMilli, portions int) (gramsMilli, error) {
	if portions <= 0 {
		return 0, errors.New("份数必须为正整数")
	}
	v := int64(g)
	if v > (1<<63-1)/int64(portions) {
		return 0, fmt.Errorf("应投量超出上限 %s 克：%s 克 × %d 份无法精确表示",
			maxGramsMilli, g, portions)
	}
	return gramsMilli(v * int64(portions)), nil
}

package release

import "fmt"

// plannedMaterial 是数量核对规则对配方中一种物料的计算结果：
// 物料编号及其在当前计划份数下的应投量（千分之一克）。
type plannedMaterial struct {
	materialNo    string
	requiredGrams gramsMilli
}

// planRequirements 是批次“应投量核对”数量规则的唯一实现：给定批次采用
// 的配方版本 r 与最终采用的计划份数 portions，按配方中的物料顺序逐项计算
// 每份克数 × 计划份数，返回每种物料的应投量。
//
// 规则对创建批次、调整草稿、读取已保存批次和构造批次查询结果完全一致：
//   - 份数必须为正整数。份数的输入语义由各入口自行处理——创建要求正整数，
//     调整草稿时传 0 表示沿用当前份数（走到这里的必是最终正份数），读取
//     已保存批次时份数非正属于数据损坏；本函数只接受已确定的最终份数；
//   - 结果必须能精确表示到千分之一克：每份克数本身已是千分之一克的整数倍，
//     整数相乘不引入更小单位，不舍入、不截断；
//   - 每种物料分别以 maxGramsMilli（9223372036854775.807 克）为上限：
//     只乘该物料自己的每份克数与份数，不与同批次其他物料的应投量相加，
//     恰好等于上限合法，超过即返回错误。错误信息指出相关物料、配方编号、
//     版本与份数；调用方再按各自场景包装错误分类（提交时为
//     ErrInvalidInput，读取已保存批次时为 ErrCorruptData 并补充批次编号）。
//
// 不能改用同编号配方的其他版本：物料列表与每份克数一律取调用方给定的 r，
// 即批次实际绑定（或本次提交最终选定）的版本。
func planRequirements(r *recipeRecord, portions int) ([]plannedMaterial, error) {
	out := make([]plannedMaterial, 0, len(r.Materials))
	for _, m := range r.Materials {
		required, err := multiplyPortions(m.GramsMilli, portions)
		if err != nil {
			return nil, fmt.Errorf("物料 %q 按配方 %q 版本 %q 以 %d 份计算的应投量不合法: %v",
				m.MaterialNo, r.RecipeNo, r.Version, portions, err)
		}
		out = append(out, plannedMaterial{materialNo: m.MaterialNo, requiredGrams: required})
	}
	return out, nil
}

// validateUnfedRequirements 是“无投料批次结果”逐物料数量核对的唯一实现，
// 创建批次、草稿调整与开始执行三类已保存成功请求在读取台账时共用这里，不再
// 各自维护一份相同的核对。mats 是保存结果中按物料列出的数量核对项，r 与
// portions 是这份结果各自依据的配方版本与份数——依据的选取仍由各调用方按
// 自己的历史判断方式决定，本函数不关心依据从何而来：
//   - 创建结果：调用方传原创建请求选定的配方版本与份数（payload），不使用
//     批次后来调整过的当前计划；
//   - 草稿调整结果：调用方传那次成功调整后结果实际采用的版本与份数（编号与
//     版本同时留空、份数为零的沿用值也以结果采用值为准），不使用批次现在的
//     计划代替；
//   - 开始执行结果：调用方传批次开始时最终固定的版本与份数。
//
// 核对规则对三类结果完全一致：
//   - 应投量依据统一由 planRequirements 按 r × portions 计算，因此千分之一克
//     精度与逐物料 maxGramsMilli 上限、份数必须为正等数量规则继续生效；
//   - mats 必须按 r 的物料顺序完整列出每种物料且恰有一项：项数不一致，或某
//     一项物料编号对不上（遗漏、重复、调换顺序或混入其他版本物料）都拒绝；
//   - 每项实投量必须为零、差额必须为应投量的负值：这些结果都是当时尚无投料
//     的快照（创建与调整是无投料草稿，开始是无投料的执行中状态），批次后来
//     再次调整、追加投料或关闭都不改变这份结果，合法的零实投与负差额不能误报。
//
// 数量按精确数值核对而非字符串写法：克数统一经 parseSignedGrams 解析后比较，
// 1 与 1.000、0 与 0.000、-1 与 -1.000 是同一数量；无法解析的写法本身就是
// 损坏。这只放宽读取核对的写法差异，请求内容的幂等匹配仍由写入路径按原文
// 比较，不在本函数处理。
//
// 本函数只负责数量规则本身，返回的错误不带错误分类，且尽量指出问题物料与
// 数量原因（项数不符时没有具体物料可指）；调用方再按各自场景用
// ErrCorruptData 包装，并补充操作类别、请求编号与批次编号。
func validateUnfedRequirements(mats []MaterialRequirement, r *recipeRecord, portions int) error {
	required, err := planRequirements(r, portions)
	if err != nil {
		return err
	}
