package release

import "testing"

func TestRefactorEdgeChecks(t *testing.T) {
	posOK := []string{"1", "1.000", "0.001", " 1 ", "9223372036854775.807"}
	for _, s := range posOK {
		if _, err := parseGrams(s); err != nil {
			t.Errorf("parseGrams(%q) 应合法: %v", s, err)
		}
	}
	posBad := []string{"0", "0.000", "-1", "-0", "", "  ", "1.2345", "1.2300", "1e3", "+1", "9223372036854775.808", "99999999999999999999999"}
	for _, s := range posBad {
		if _, err := parseGrams(s); err == nil {
			t.Errorf("parseGrams(%q) 应拒绝", s)
		}
	}
	signedOK := map[string]gramsMilli{"0": 0, "0.000": 0, "-1": -1000, "-1.000": -1000, "1": 1000, "1.000": 1000, "-9223372036854775.807": -maxGramsMilli}
	for s, want := range signedOK {
		got, err := parseSignedGrams(s)
		if err != nil || got != want {
			t.Errorf("parseSignedGrams(%q) = %v, %v; 期望 %v", s, got, err, want)
		}
	}
	signedBad := []string{"", "  ", "1.2345", "1e3", "+1", "-9223372036854775.808", "99999999999999999999999", "-99999999999999999999999"}
	for _, s := range signedBad {
		if _, err := parseSignedGrams(s); err == nil {
			t.Errorf("parseSignedGrams(%q) 应拒绝", s)
		}
	}
	// 等值写法
	a, _ := parseSignedGrams("1")
	b, _ := parseSignedGrams("1.000")
	if a != b {
		t.Error("1 与 1.000 应相等")
	}
}
EOF
cp /tmp/decimal_check_test.go release/zz_decimal_check_test.go && go test ./release/ -run TestRefactorEdgeChecks -v; rm release/zz_decimal_check_test.go
